(function(root){'use strict';const S=root.KERN_SHAPES||(typeof require==='function'?require('./room-shapes.js'):null);
const EPS=1e-5;
function solve(constraints,vertices,tolerance){
 constraints=constraints.filter(c=>Math.abs(c.k)<=tolerance).sort((a,b)=>Math.abs(a.k)-Math.abs(b.k)).slice(0,64);
 const candidates=[...vertices];for(const c of constraints)candidates.push({dx:c.nx*c.k,dy:c.ny*c.k});
 for(let i=0;i<constraints.length;i++)for(let j=i+1;j<constraints.length;j++){const a=constraints[i],b=constraints[j],det=a.nx*b.ny-a.ny*b.nx;if(Math.abs(det)<.05)continue;const dx=(a.k*b.ny-a.ny*b.k)/det,dy=(a.nx*b.k-a.k*b.nx)/det;if(Math.hypot(dx,dy)<=tolerance*Math.SQRT2+EPS&&a.valid(dx,dy)&&b.valid(dx,dy))candidates.push({dx,dy});}
 let best=null;for(const c of candidates){const distance=Math.hypot(c.dx,c.dy);if(distance>tolerance*Math.SQRT2+EPS)continue;const matches=constraints.filter(a=>Math.abs(a.nx*c.dx+a.ny*c.dy-a.k)<EPS&&a.valid(c.dx,c.dy));let rank=c.kind==='vertex'?2:matches.length?1:0;if(matches.some((a,i)=>matches.slice(i+1).some(b=>Math.abs(a.nx*b.ny-a.ny*b.nx)>.05)))rank=2;if(!rank)continue;const support=new Set(matches.map(a=>a.id)).size;if(!best||rank>best.rank||rank===best.rank&&(support>best.support||support===best.support&&distance<best.distance-EPS))best={...c,rank,support,distance,matches};}
 if(!best)return null;const guides=[...new Map(best.matches.map(c=>[c.id,{edge:c.edge,room:c.room}])).values()];return{...best,kind:best.kind||'edge',guides,edge:guides[0]?.edge,room:best.room||guides[0]?.room};
}
function constraint(p,e,room,id,inverse=false){const dx=e.b[0]-e.a[0],dy=e.b[1]-e.a[1],len=Math.hypot(dx,dy);if(len<EPS)return null;const nx=-dy/len,ny=dx/len,k=nx*(e.a[0]-p[0])+ny*(e.a[1]-p[1]),sign=inverse?-1:1;return{nx:nx*sign,ny:ny*sign,k,edge:e,room,id,valid(x,y){const q=S.project({x:p[0]+x*sign,y:p[1]+y*sign},e);return q.distance<EPS;}};}
function point(p,rooms,exclude,tolerance){const constraints=[],vertices=[];for(const r of rooms){if(exclude.has(r.id))continue;for(const q of S.points(r)){const dx=q[0]-p.x,dy=q[1]-p.y;if(Math.hypot(dx,dy)<=tolerance)vertices.push({dx,dy,kind:'vertex',room:r.id});}S.edges(r).forEach((e,i)=>{const c=constraint([p.x,p.y],e,r.id,r.id+':'+i);if(c)constraints.push(c);});}const hit=solve(constraints,vertices,tolerance);return hit?{...hit,x:p.x+hit.dx,y:p.y+hit.dy}:null;}
function translation(input,rooms,exclude,tolerance){const moving=Array.isArray(input)?input:[input],constraints=[],vertices=[];for(const r of moving)for(const other of rooms){if(exclude.has(other.id))continue;const targets=S.points(other),edges=S.edges(other),sources=S.points(r);for(const p of sources){for(const q of targets){const dx=q[0]-p[0],dy=q[1]-p[1];if(Math.hypot(dx,dy)<=tolerance)vertices.push({dx,dy,x:q[0],y:q[1],kind:'vertex',room:other.id});}edges.forEach((e,i)=>{const c=constraint(p,e,other.id,other.id+':'+i);if(c)constraints.push(c);});}for(const p of targets)S.edges(r).forEach((e,i)=>{const c=constraint(p,e,other.id,r.id+':reverse:'+i+':'+other.id,true);if(c)constraints.push(c);});}return solve(constraints,vertices,tolerance);}
function angle(r,delta,rooms,exclude,tolerance=4){let best=null;for(const e of S.edges(r).filter(e=>!e.curved)){const source=Math.atan2(e.b[1]-e.a[1],e.b[0]-e.a[0])*180/Math.PI;for(const other of rooms){if(exclude.has(other.id))continue;for(const edge of S.edges(other).filter(e=>!e.curved)){const target=Math.atan2(edge.b[1]-edge.a[1],edge.b[0]-edge.a[0])*180/Math.PI;let diff=((target-source-delta)%180+270)%180-90;if(Math.abs(diff)<=tolerance&&(!best||Math.abs(diff)<Math.abs(best.diff)))best={delta:delta+diff,diff,edge,kind:'angle',room:other.id};}}}return best;}
const api={point,translation,angle};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.KERN_ROOM_SNAP=api;
})(typeof window!=='undefined'?window:globalThis);
